// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {demo} from "../src/demo.sol";

contract InvMutTest is Test {
    demo c;
    function setUp() public { c = new demo(); }

    function testFuzz_property(address from, uint256 v, address a1, address a2, address a3) public {
        vm.assume(from != address(0));
        vm.assume(a1 != address(0) && a2 != address(0) && a3 != address(0));
        vm.assume(a1 != a2 && a1 != a3 && a2 != a3);

        Recorder rec = new Recorder();
        address[] memory tos = new address[](3);
        tos[0] = a1;
        tos[1] = a2;
        tos[2] = a3;

        address expectedCallee = address(rec);
        (bool ok, ) = address(c).call(
            abi.encodeWithSignature(
                "transfer(address,address,address[],uint256)",
                from, expectedCallee, tos, v
            )
        );
        assertTrue(ok, "reference call must succeed");

        (, address[] memory targets, uint256[] memory amounts) = rec.getRecord();
        assertEq(targets.length, 3, "reference must make exactly 3 calls");
        assertEq(targets[0], a1, "first target must be a1");
        assertEq(targets[1], a2, "second target must be a2");
        assertEq(targets[2], a3, "third target must be a3");
        assertEq(amounts[0], v, "first amount");
        assertEq(amounts[1], v, "second amount");
        assertEq(amounts[2], v, "third amount");
    }
}

contract Recorder {
    address[] public targets;
    uint256[] public amounts;

    function getRecord() external view returns (uint256, address[] memory, uint256[] memory) {
        return (targets.length, targets, amounts);
    }

    fallback(bytes calldata data) external payable returns (bytes memory) {
        if (data.length == 100) {
            bytes4 sel;
            assembly { sel := calldataload(0) }
            if (sel == bytes4(keccak256("transferFrom(address,address,uint256)"))) {
                address to;
                uint256 amount;
                assembly {
                    to := calldataload(36)
                    amount := calldataload(68)
                }
                targets.push(to);
                amounts.push(amount);
            }
        }
        return "";
    }
}
